function money(value: number) { return `₹${Math.round(value).toLocaleString('en-IN')}`; }
function dateLabel(value?: string) { return value ? new Date(value).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' }) : 'Today'; }

function Notice({ children, tone = 'info' }: { children: ReactNode; tone?: 'info' | 'success' | 'warn' }) {
  return <div className={`flex items-start gap-3 rounded-xl border px-4 py-3 text-sm ${tone === 'success' ? 'border-primary/20 bg-primary/8 text-primary' : tone === 'warn' ? 'border-accent/25 bg-accent/10 text-foreground' : 'border-chart-4/20 bg-chart-4/8 text-foreground'}`} data-testid="status-notice"><CircleAlert className="mt-0.5 size-4 shrink-0" /><span>{children}</span></div>;
}

function DemoTag() { return <span className="inline-flex items-center gap-1 rounded-full bg-secondary px-2.5 py-1 font-mono-data text-[10px] font-bold uppercase tracking-[.08em] text-secondary-foreground" data-testid="badge-prototype"><span className="size-1.5 rounded-full bg-accent" />Prototype data</span>; }
function Verified() { return <span className="inline-flex items-center gap-1 text-xs font-semibold text-primary"><BadgeCheck className="size-4" />Verified</span>; }
function Skeleton({ className = '' }: { className?: string }) { return <div className={`animate-pulse rounded-lg bg-muted ${className}`} data-testid="loading-skeleton" />; }

function DataState({ loading, error, empty, children, onRetry }: { loading?: boolean; error?: boolean; empty?: boolean; children: ReactNode; onRetry?: () => void }) {
  if (loading) return <div className="space-y-3"><Skeleton className="h-5 w-44" /><Skeleton className="h-28 w-full" /><Skeleton className="h-20 w-full" /></div>;
  if (error) return <Notice tone="warn"><span>Live data is taking a pause. Prototype records are shown so you can continue.</span>{onRetry && <button onClick={onRetry} className="ml-2 underline" data-testid="button-retry">Try again</button>}</Notice>;
  if (empty) return <div className="rounded-2xl border border-dashed border-border bg-card p-10 text-center"><Leaf className="mx-auto mb-3 size-7 text-primary/50" /><p className="font-semibold">No records yet</p><p className="mt-1 text-sm text-muted-foreground">Your next verified step will appear here.</p></div>;
  return <>{children}</>;
}

