function PageHead({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2 font-mono-data text-[10px] font-bold uppercase tracking-[.15em] text-primary"><span className="size-1.5 rounded-full bg-accent" />{eyebrow}</div><h1 className="font-display text-3xl tracking-tight text-foreground sm:text-4xl">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action && <div className="shrink-0">{action}</div>}</div>;
}
function Button({ children, secondary = false, className = '', onClick, type = 'button', disabled = false }: { children: ReactNode; secondary?: boolean; className?: string; onClick?: () => void; type?: 'button' | 'submit'; disabled?: boolean }) {
  return <button type={type} disabled={disabled} onClick={onClick} className={`inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-4 text-sm font-semibold transition-all ${secondary ? 'border border-border bg-card text-foreground hover:bg-muted' : 'bg-primary text-primary-foreground hover:-translate-y-0.5 hover:shadow-lg hover:shadow-primary/15'} ${disabled ? 'cursor-not-allowed opacity-50' : ''} ${className}`} data-testid="button-action">{children}</button>;
}
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`rounded-2xl border border-card-border bg-card p-5 shadow-[0_5px_18px_hsl(154_24%_16%/.035)] ${className}`}>{children}</section>; }
function SectionTitle({ children, action }: { children: ReactNode; action?: ReactNode }) { return <div className="mb-4 flex items-center justify-between gap-3"><h2 className="font-display text-xl tracking-tight">{children}</h2>{action}</div>; }
function Stat({ label, value, detail, trend }: { label: string; value: string; detail?: string; trend?: 'up' | 'down' }) { return <div><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 font-display text-2xl">{value}</p>{detail && <p className={`mt-1 flex items-center gap-1 text-xs ${trend === 'down' ? 'text-destructive' : 'text-primary'}`}>{trend === 'down' ? <TrendingDown className="size-3" /> : trend === 'up' ? <TrendingUp className="size-3" /> : null}{detail}</p>}</div>; }
function MiniBars({ values, color = 'bg-primary' }: { values: number[]; color?: string }) { const max = Math.max(...values); return <div className="flex h-20 items-end gap-1.5">{values.map((v, i) => <div key={i} className={`flex-1 rounded-t-sm ${color} opacity-${i === values.length - 1 ? '100' : '50'}`} style={{ height: `${Math.max(12, (v / max) * 100)}%` }} />)}</div>; }
function Progress({ value, label, sub }: { value: number; label: string; sub?: string }) { return <div><div className="mb-1.5 flex justify-between text-xs"><span className="font-medium">{label}</span><span className="font-mono-data text-muted-foreground">{sub ?? `${value}%`}</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${value}%` }} /></div></div>; }

